import { lstatSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { frontmatterText, quotedScalar } from '../../.cratis/ai/harnesses/pi/extensions/shared/frontmatter.ts';

/** Identifies adapters generated by setup, including stale outputs. */
export const copilotMarker = '<!-- cratis-ai: generated Copilot instructions.';
const marker = `${copilotMarker} Do not edit; rules/ is the source. -->`;
export const copilotInstructionsDirectory = 'harnesses/copilot/instructions';

/** A portable generated adapter, relative to the corpus root. */
export interface CopilotInstruction {
    path: string;
    content: string;
}

function rules(corpus: string): Array<{ name: string; content: string }> {
    return readdirSync(join(corpus, 'rules')).filter(name => name.endsWith('.md')).sort()
        .map(name => ({ name, content: readFileSync(join(corpus, 'rules', name), 'utf8') }));
}

function applyTo(content: string): RegExpExecArray | null {
    const fields = frontmatterText(content);
    return fields === undefined ? null : /^applyTo:([^\n]*)(?:\n[ \t]+[^\n]*)*/m.exec(fields);
}

/** Generate copied path rules, not symlinks: consumers receive this directory as corpus files. */
export function copilotInstructions(corpus: string): CopilotInstruction[] {
    const instructions: CopilotInstruction[] = [];
    for (const { name, content } of rules(corpus)) {
        const match = applyTo(content);
        if (!match) continue;
        const raw = match[1].trim();
        const quoted = quotedScalar(raw);
        let transformed = content;
        if (quoted === undefined || quoted.trim() === '') {
            // Normalize simple scalar/list forms only; unsupported YAML must not broaden scope.
            const globs = raw === ''
                ? match[0].split('\n').slice(1).map(line => /^\s+-\s+(.+)$/.exec(line)?.[1]).map(value => value && (quotedScalar(value) ?? value))
                : [raw];
            if (globs.length === 0 || globs.some(value => !value || /^[\[\]{|>]/.test(value) || value.includes(' #'))) {
                throw new Error(`rules/${name}: applyTo must be a glob string or a list of glob strings.`);
            }
            transformed = content.replace(match[0], `applyTo: ${JSON.stringify(globs.join(','))}`);
        }
        const end = transformed.indexOf('\n---\n', 4) + 5;
        instructions.push({
            path: `${copilotInstructionsDirectory}/${name.slice(0, -3)}.instructions.md`,
            content: `${transformed.slice(0, end)}${marker}\n${transformed.slice(end)}`,
        });
    }
    return instructions;
}

/** Keep universal rules at the repository-wide root, never duplicated as path adapters. */
export function copilotRootInstructions(corpus: string): string {
    return `${marker}\n\n${rules(corpus).filter(rule => !applyTo(rule.content)).map(rule => rule.content).join('\n\n')}`;
}

/** Report missing, changed, non-file and orphaned generated adapters without following symlinks. */
export function checkCopilotInstructions(corpus: string): string[] {
    const expected = copilotInstructions(corpus);
    const directory = join(corpus, copilotInstructionsDirectory);
    const failures: string[] = [];
    let names: string[];
    try {
        if (!lstatSync(directory).isDirectory()) return [`${copilotInstructionsDirectory} is not a generated adapter directory.`];
        names = readdirSync(directory);
    } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
        return expected.length > 0 ? expected.map(file => `${file.path} is missing.`) : [`${copilotInstructionsDirectory} is missing.`];
    }
    for (const file of expected) {
        try {
            const path = join(corpus, file.path);
            if (!lstatSync(path).isFile() || readFileSync(path, 'utf8') !== file.content) failures.push(`${file.path} is stale (regenerate from rules/).`);
        } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
            failures.push(`${file.path} is missing.`);
        }
    }
    const expectedNames = new Set(expected.map(file => file.path.split('/').pop()));
    for (const name of names) {
        if (!expectedNames.has(name)) failures.push(`${copilotInstructionsDirectory}/${name} has no path-scoped rule (orphan).`);
    }
    return failures;
}
